"""
Mo-dun quan ly hinh anh mau (Templates) va tai nguyen nhung cho Auto Rally.
Tu dong giai ma chuoi Base64 thanh mang hinh anh OpenCV va luu bo nho dem (cache).
"""

import base64
from typing import Optional
import cv2
import numpy as np

# Template tieu de "Tong Tan Cong!" mau xanh cyan tren nen vang vien den
RALLY_HEADER_TEMPLATE_B64: str = """"""

# Cache doi tuong anh NumPy trong RAM de khong phai giai ma Base64 lap lai
_cached_template: Optional[np.ndarray] = None


def get_rally_template() -> np.ndarray:
    """Tra ve hinh anh mau cua tieu de Rally duoi dang mang BGR NumPy."""
    global _cached_template
    if _cached_template is None:
        raw_bytes = base64.b64decode(RALLY_HEADER_TEMPLATE_B64)
        _cached_template = cv2.imdecode(np.frombuffer(raw_bytes, dtype=np.uint8), cv2.IMREAD_COLOR)
    return _cached_template
